UPDATE INTRODUCTION 
   SET INTRODUCTION_NAME = #{introductionName}
 WHERE INTRODUCTION_NO = #{introductionNo}
   AND USER_ID = #{userId}

UPDATE INTRODUCTION 
   SET INTRODUCTION_DELETE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
 WHERE INTRODUCTION_NO = #{introductionNo}
